inline bool evaluate(const float* x, double& score, bool& novelty) {
  double z[FEATURES];
  for (int i=0; i<FEATURES; ++i) {
    if (!std::isfinite(x[i])) return false;
    z[i] = (double(x[i])-scale_mean[i])/scale_std[i]-location[i];
  }
  double distance2 = 0;
  for (int i=0; i<FEATURES; ++i)
    for (int j=0; j<FEATURES; ++j)
      distance2 += z[i]*precision[i*FEATURES+j]*z[j];
  if (!std::isfinite(distance2)) return false;
  score = std::sqrt(distance2 > 0 ? distance2 : 0);
  novelty = score > threshold;
  return true;
}
